window.S17Page={"sceneId":"r4","caseId":"s17x-r4-lab-audit","name":"化验数据智能审核","title":"化验数据智能审核：从原文单位到指标关系","summary":"先读懂样品、单位与测量条件，再把范围审核和多变量关系审核放在同一张化验表中比较。","directory":"expansion-cases","caseVersion":"1.2.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){
'use strict';
const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:0;
function rng(seed){let s=seed>>>0;return()=>((s=Math.imul(1664525,s)+1013904223>>>0)/4294967296);}
function solve(A,b){let M=A.map((r,i)=>r.concat(b[i])),n=b.length;for(let k=0;k<n;k++){let p=k;for(let i=k+1;i<n;i++)if(Math.abs(M[i][k])>Math.abs(M[p][k]))p=i;[M[k],M[p]]=[M[p],M[k]];let d=M[k][k];for(let j=k;j<=n;j++)M[k][j]/=d;for(let i=0;i<n;i++)if(i!==k){let f=M[i][k];for(let j=k;j<=n;j++)M[i][j]-=f*M[k][j];}}return M.map(r=>r[n]);}
function clean(n,seed){const r=rng(seed);return Array.from({length:n},(_,i)=>{let density=805+r()*70,sulfur=.15+r()*1.6,viscosity=2.1+.052*(density-805)+1.35*sulfur+(r()-.5)*.4;return{id:'L'+String(i+1).padStart(3,'0'),density,sulfur,viscosity};});}
const vector=r=>[1,(r.density-840)/35,r.sulfur];
function fit(rows){const X=rows.map(vector),A=[0,1,2].map(j=>[0,1,2].map(k=>X.reduce((s,x)=>s+x[j]*x[k],0)+(j===k&&j?.01:0))),b=[0,1,2].map(j=>X.reduce((s,x,i)=>s+x[j]*rows[i].viscosity,0));return{coeff:solve(A,b),n:rows.length};}
const predict=(r,m)=>vector(r).reduce((s,x,i)=>s+x*m.coeff[i],0);
function fixture(mode='mixed'){const rows=clean(30,170406),truth=[];const text=rows.map((r,i)=>{let d=r.density.toFixed(1),s=r.sulfur.toFixed(3),v=r.viscosity.toFixed(2),u='kg/m3',type='正常';if(i===3&&(mode==='mixed'||mode==='unit')){d=(r.density/1000).toFixed(4);u='kg/L';type='合法单位换算';}if((mode==='mixed'||mode==='unit')&&i===8){d=(r.density/1000).toFixed(4);type='单位错配';}if((mode==='mixed'||mode==='relationship')&&[12,19,25].includes(i)){v=(r.viscosity+2.8).toFixed(2);type='关系冲突';}if(mode==='mixed'&&i===16){s='-0.5';type='负数';}if(mode==='mixed'&&i===22){v='缺失';type='缺失';}truth.push({id:r.id,type,abnormal:!['正常','合法单位换算'].includes(type)});return`样品 ${r.id}; 密度=${d} ${u}; 硫=${s} %; 黏度=${v} mm2/s`;}).join('\n');return{text,truth};}
function parse(text){return text.trim().split(/\n+/).filter(Boolean).map((line,index)=>{const id=(line.match(/样品\s*([\w-]+)/)||[])[1]||'ROW'+(index+1),d=line.match(/密度\s*[=:：]\s*([-+\d.eE]+)\s*(kg\/m3|kg\/L|g\/cm3)/i),s=line.match(/硫\s*[=:：]\s*([-+\d.eE]+)\s*%/),v=line.match(/黏度\s*[=:：]\s*([-+\d.eE]+)\s*mm2\/s/);return{id,line,density:d?Number(d[1])*(d[2].toLowerCase()==='kg/m3'?1:1000):null,sulfur:s?Number(s[1]):null,viscosity:v?Number(v[1]):null,originalUnit:d?.[2]??'未识别',converted:!!d&&d[2].toLowerCase()!=='kg/m3',parseIssue:!d||!s||!v};});}
// Rules and the fitted relationship inspect submitted values; injected-error truth is evaluation-only.
function infer(rows,model,threshold){return rows.map(r=>{let reasons=[];if(r.parseIssue||[r.density,r.sulfur,r.viscosity].some(v=>!Number.isFinite(v)))reasons.push('字段缺失或格式未识别');if(r.density!==null&&(r.density<780||r.density>900))reasons.push('密度超出演示范围780–900 kg/m³');if(r.sulfur!==null&&(r.sulfur<0||r.sulfur>3))reasons.push('硫质量分数超出0–3%');if(r.viscosity!==null&&(r.viscosity<.5||r.viscosity>12))reasons.push('运动黏度超出0.5–12 mm²/s');const expected= !r.parseIssue?predict(r,model):null,residual=expected===null?null:r.viscosity-expected,relationship=expected!==null&&!reasons.length&&Math.abs(residual)>threshold;return{...r,expected,residual,ruleFlag:reasons.length>0,flag:reasons.length>0||relationship,reasons:reasons.concat(relationship?'密度与硫含量不能解释当前黏度':[])};});}
function evaluate(rows,truth,key){let tp=0,fp=0,fn=0,tn=0;const map=new Map(truth.map(r=>[r.id,r]));for(let r of rows){const t=map.get(r.id);if(!t)continue;if(r[key]&&t.abnormal)tp++;else if(r[key])fp++;else if(t.abnormal)fn++;else tn++;}return{n:tp+fp+fn+tn,tp,fp,fn,tn,precision:tp+fp?tp/(tp+fp):null,recall:tp+fn?tp/(tp+fn):null};}
function run(params={}){const p={mode:'mixed',sensitivity:3,...params},train=clean(80,170401),validation=clean(30,170402),model=fit(train),sd=Math.sqrt(mean(validation.map(r=>(r.viscosity-predict(r,model))**2))),threshold=p.sensitivity*sd,source=fixture(p.mode),custom=typeof p.text==='string'&&p.text!==source.text,prediction=infer(parse(p.text??source.text),model,threshold);return{sceneId:'r4',params:{mode:p.mode,sensitivity:p.sensitivity},dataNature:'虚构馏分样品，固定种子；密度kg/m³、硫质量分数%、40°C运动黏度mm²/s。范围与关系仅为本课程生成器设定。',model,threshold,validationRMSE:sd,prediction,evaluationTruth:custom?[]:source.truth,metrics:custom?null:{model:evaluate(prediction,source.truth,'flag'),baseline:evaluate(prediction,source.truth,'ruleFlag')},evaluationAvailable:!custom,split:{train:80,validation:30,test:prediction.length,truthUsedByPrediction:false}};}
g.R4Core={run,fixture,parse,fit,infer,predict};
})(globalThis);

